/**
 * issue #59: bridges a small allow-listed set of EXISTING Node-RED runtime
 * events (the native `node-status` event, and the native `comms` event
 * ONLY when `topic === "debug"`) from a headless runner ("B") to an
 * ordinary, separately-running Node-RED editor ("A") so A's UNTOUCHED
 * Debug sidebar and canvas status renderer keep working when execution has
 * been split across processes (issue #39).
 *
 * issue #85 extends the same one-way bridge with exactly one more native
 * event: the native `runtime-event` Node-RED emits with
 * `{id:"runtime-state", payload:{state, ...}}` (see
 * `@node-red/runtime/lib/flows/index.js`). A is intentionally configured
 * with `runtimeFlowState: "stop"` (issue #73) so it never instantiates the
 * deployed flow locally - but that also means A's OWN local runtime keeps
 * emitting `runtime-state: "stop"` on every boot/redeploy, which would
 * otherwise make the stock editor client mark Inject/Debug node buttons as
 * unusable even while B (the real, live runtime) is started and issue #61
 * already proxies those actions to B. Relaying B's `runtime-state` fixes
 * that UX regression without giving A a second live runtime.
 *
 * This is observability transport ONLY:
 *   - one-way, B -> A - never bidirectional, never a control/RPC channel;
 *   - never blocks or slows Temporal execution - a slow/dead/disconnected
 *     receiver can only fail to receive a write, it can never throw back
 *     into `@node-red/util`'s shared event emitter or backpressure a node;
 *   - Debug output is transient (lost while disconnected, no queue/history);
 *   - node-status keeps only the LATEST status per node id, in-memory only,
 *     on B - not durable, cleared on runner restart;
 *   - runtime-state keeps only the LATEST state, in-memory only, on B -
 *     not durable, cleared on runner restart.
 *
 * Nothing here reimplements `@node-red/runtime/lib/api/comms.js` or
 * `@node-red/editor-api/lib/editor/comms.js` - both remain the actual
 * comms/Debug/runtime-state implementation; this module only re-broadcasts
 * the same native event shapes onto A's copy of `@node-red/util`'s events
 * singleton so A's own untouched comms stack picks them up exactly like it
 * would for one of its own local nodes/its own local runtime.
 *
 * Wire format: newline-delimited JSON over one chunked HTTP response body,
 * one record per line:
 *   {"type":"node-status","event":{"id":"n1","status":{...}}}
 *   {"type":"comms","event":{"topic":"debug","data":{...}}}
 *   {"type":"runtime-state","event":{"id":"runtime-state","payload":{...},"retain":true}}
 * The outer `type` is only a discriminator selecting which native event to
 * re-emit on the receiving side - the inner `event` is the native,
 * unmodified Node-RED event object in both directions. For
 * `runtime-state`, the native event name re-emitted on A's side is
 * `runtime-event` (matching how B itself emits it), never `runtime-state`.
 */

"use strict";

const NODE_STATUS = "node-status";
const COMMS = "comms";
const DEBUG_TOPIC = "debug";
const RUNTIME_EVENT = "runtime-event";
const RUNTIME_STATE = "runtime-state";

const DEFAULT_PATH = "/_node-red-temporal/runtime-events";
const DEFAULT_MIN_BACKOFF_MS = 500;
const DEFAULT_MAX_BACKOFF_MS = 15000;

/** True only for the one comms event this bridge ever forwards: Debug output. */
function isForwardableCommsEvent(event) {
    return !!event && typeof event === "object" && event.topic === DEBUG_TOPIC;
}

/**
 * True only for the one `runtime-event` shape this bridge ever forwards:
 * Node-RED's native runtime-state notification
 * (`events.emit("runtime-event",{id:"runtime-state",...})`). Every other
 * `runtime-event` id (e.g. future additions) is rejected - this module is
 * deliberately NOT a generic runtime-event tunnel.
 */
function isForwardableRuntimeEvent(event) {
    return !!event && typeof event === "object" && event.id === RUNTIME_STATE;
}

/** Mirrors `@node-red/runtime/lib/api/comms.js`'s own "cleared status" test. */
function isEmptyStatus(status) {
    return !status || (!status.text && !status.fill && !status.shape);
}

/** @param {"node-status"|"comms"} type @param {object} event */
function encodeRecord(type, event) {
    return `${JSON.stringify({ type, event })}\n`;
}

/**
 * Parses and allow-list-validates a single NDJSON line.
 * @returns {{type:string, event:object}|null} null for blank/malformed/
 *   disallowed lines - callers must ignore, never throw.
 */
function decodeLine(line) {
    if (typeof line !== "string") {
        return null;
    }
    const trimmed = line.trim();
    if (!trimmed) {
        return null;
    }
    let parsed;
    try {
        parsed = JSON.parse(trimmed);
    } catch (err) {
        return null;
    }
    if (!parsed || typeof parsed !== "object") {
        return null;
    }
    if (parsed.type !== NODE_STATUS && parsed.type !== COMMS && parsed.type !== RUNTIME_STATE) {
        return null;
    }
    if (!parsed.event || typeof parsed.event !== "object") {
        return null;
    }
    if (parsed.type === COMMS && !isForwardableCommsEvent(parsed.event)) {
        return null;
    }
    if (parsed.type === RUNTIME_STATE && !isForwardableRuntimeEvent(parsed.event)) {
        return null;
    }
    return { type: parsed.type, event: parsed.event };
}

/**
 * Tracks only the LATEST `node-status` event per node id. Not durable -
 * a fresh instance (i.e. a runner restart) starts empty.
 */
function createStatusSnapshot() {
    const byId = new Map();
    return {
        /** @param {object} event native node-status event: {id, status} */
        apply(event) {
            if (!event || !event.id) {
                return;
            }
            if (isEmptyStatus(event.status)) {
                byId.delete(event.id);
            } else {
                byId.set(event.id, event);
            }
        },
        /** @returns {Array<object>} retained events, in no particular order */
        list() {
            return Array.from(byId.values());
        }
    };
}

/**
 * Tracks only the LATEST native `runtime-state` `runtime-event` (mirrors
 * `createStatusSnapshot()`'s pattern, but there is only ever one current
 * runtime state, never a per-id map). Not durable - a fresh instance (i.e.
 * a runner restart) starts with no retained state, and a newly-connecting
 * receiver simply gets nothing replayed until B's own runtime next emits
 * one (which it always does at least once on boot/deploy).
 */
function createRuntimeStateSnapshot() {
    let latest = null;
    return {
        /** @param {object} event native runtime-event: {id:"runtime-state", payload, retain} */
        apply(event) {
            if (!isForwardableRuntimeEvent(event)) {
                return;
            }
            latest = event;
        },
        /** @returns {object|null} the retained event, or null if none yet */
        get() {
            return latest;
        }
    };
}

/**
 * Builds B's side of the bridge: an Express-compatible request handler plus
 * a `close()` to release its permanent `node-status`/`runtime-event`
 * listeners (used to keep the retained snapshots current even with zero
 * connected receivers).
 * @param {object} options
 * @param {object} options.events - `@node-red/util`'s events singleton.
 * @returns {{handler:function(req,res), close:function()}}
 */
function createRuntimeEventsRoute(options) {
    options = options || {};
    const events = options.events;
    if (!events || typeof events.on !== "function" || typeof events.emit !== "function") {
        throw new Error("createRuntimeEventsRoute requires options.events (@node-red/util events singleton)");
    }

    const snapshot = createStatusSnapshot();
    const trackStatus = (event) => snapshot.apply(event);
    events.on(NODE_STATUS, trackStatus);

    const runtimeStateSnapshot = createRuntimeStateSnapshot();
    const trackRuntimeState = (event) => runtimeStateSnapshot.apply(event);
    events.on(RUNTIME_EVENT, trackRuntimeState);

    function safeWrite(res, chunk) {
        if (res.writableEnded || res.destroyed) {
            return;
        }
        try {
            res.write(chunk);
        } catch (err) {
            // A slow/dead HTTP peer must never impact runtime event emission.
        }
    }

    function handler(req, res) {
        res.writeHead(200, {
            "Content-Type": "application/x-ndjson",
            "Cache-Control": "no-cache",
            Connection: "keep-alive"
        });
        if (typeof res.flushHeaders === "function") {
            res.flushHeaders();
        }

        // Current snapshots first, then live events - so a newly-connected
        // receiver's editor immediately reflects every live node's status
        // and B's current runtime state (e.g. Inject/Debug buttons become
        // usable right away instead of waiting for B's next deploy/state
        // change).
        snapshot.list().forEach((event) => {
            safeWrite(res, encodeRecord(NODE_STATUS, event));
        });
        const latestRuntimeState = runtimeStateSnapshot.get();
        if (latestRuntimeState) {
            safeWrite(res, encodeRecord(RUNTIME_STATE, latestRuntimeState));
        }

        const onStatus = (event) => safeWrite(res, encodeRecord(NODE_STATUS, event));
        const onComms = (event) => {
            if (isForwardableCommsEvent(event)) {
                safeWrite(res, encodeRecord(COMMS, event));
            }
        };
        const onRuntimeEvent = (event) => {
            if (isForwardableRuntimeEvent(event)) {
                safeWrite(res, encodeRecord(RUNTIME_STATE, event));
            }
        };
        events.on(NODE_STATUS, onStatus);
        events.on(COMMS, onComms);
        events.on(RUNTIME_EVENT, onRuntimeEvent);

        let detached = false;
        function detach() {
            if (detached) {
                return;
            }
            detached = true;
            events.removeListener(NODE_STATUS, onStatus);
            events.removeListener(COMMS, onComms);
            events.removeListener(RUNTIME_EVENT, onRuntimeEvent);
        }
        req.on("close", detach);
        res.on("close", detach);
        res.on("error", detach);
    }

    function close() {
        events.removeListener(NODE_STATUS, trackStatus);
        events.removeListener(RUNTIME_EVENT, trackRuntimeState);
    }

    return { handler, close };
}

/**
 * Builds A's side of the bridge: connects to B's streaming endpoint,
 * parses/allow-list-validates NDJSON records, and re-emits the native event
 * on A's own `@node-red/util` events singleton so A's untouched comms/UI
 * stack handles it normally. Reconnects with a modest bounded exponential
 * backoff; never throws out of `start()`.
 * @param {object} options
 * @param {object} options.events - A's `@node-red/util` events singleton.
 * @param {string} options.target - B's base URL, e.g. "http://localhost:1881".
 * @param {string} [options.token] - bearer token, reusing the same
 *   admin token already configured for `createRemoteDeployStorage()`.
 * @param {string} [options.path] - defaults to `/_node-red-temporal/runtime-events`.
 * @param {function} [options.fetch] - injectable fetch, defaults to global fetch.
 * @param {object} [options.log] - injectable logger (`.warn`/`.debug`), defaults to console.
 * @param {number} [options.minBackoffMs]
 * @param {number} [options.maxBackoffMs]
 * @returns {{start:function(), stop:function()}}
 */
function createRuntimeEventsReceiver(options) {
    options = options || {};
    const events = options.events;
    if (!events || typeof events.emit !== "function") {
        throw new Error("createRuntimeEventsReceiver requires options.events (@node-red/util events singleton)");
    }
    if (!options.target) {
        throw new Error("createRuntimeEventsReceiver requires options.target (runner B's base URL)");
    }
    const target = String(options.target).replace(/\/+$/, "");
    const path = options.path || DEFAULT_PATH;
    const token = options.token;
    const fetchImpl = options.fetch || (typeof fetch === "function" ? fetch : undefined);
    if (typeof fetchImpl !== "function") {
        throw new Error("createRuntimeEventsReceiver requires a global fetch implementation (Node >=18) or an injected options.fetch");
    }
    const log = options.log || console;
    const minBackoffMs = options.minBackoffMs || DEFAULT_MIN_BACKOFF_MS;
    const maxBackoffMs = options.maxBackoffMs || DEFAULT_MAX_BACKOFF_MS;

    let stopped = true;
    let active = false;
    let backoff = minBackoffMs;
    let currentAbort = null;
    let reconnectTimer = null;

    // issue #85: A's own local runtime (intentionally always
    // `runtimeFlowState: "stop"`, issue #73) still emits its own native
    // `runtime-event`/`runtime-state` on every local boot/deploy. Left
    // alone, that local "stop" would keep overwriting the browser-visible
    // state every time it happens AFTER B's relayed state was applied
    // (verified: `@node-red/runtime/lib/flows/index.js` emits its own
    // `runtime-state: "stop"` from `start()` on every Deploy, not just once
    // at boot - see `start()`'s early-return path when
    // `runtimeFlowState === "stop"`). `events` is a single shared emitter -
    // both A's local runtime code and this receiver call
    // `events.emit("runtime-event", ...)` on it, and Node-RED's own
    // untouched `@node-red/runtime/lib/api/comms.js` just forwards whatever
    // it observes to the browser as `notification/runtime-state`; the
    // stock editor client (`state = msg.state`) simply keeps the LAST value
    // it receives. So the fix is about emission ORDER, not about
    // suppressing A's own local emission (which this module must never
    // touch/patch) - whenever A's own local runtime-state event fires,
    // immediately re-emit B's last known state again afterwards, in the
    // same synchronous tick, so it is always the last one comms.js
    // forwards. `correctingLocalState` guards against this receiver's own
    // corrective re-emit being mistaken for a new local event (infinite
    // recursion) - `events.emit()` calls listeners synchronously/
    // re-entrantly.
    let latestRemoteState = null;
    let correctingLocalState = false;

    function onLocalRuntimeEvent(event) {
        if (correctingLocalState) {
            return;
        }
        if (!latestRemoteState || !event || event.id !== RUNTIME_STATE) {
            return;
        }
        correctingLocalState = true;
        try {
            events.emit(RUNTIME_EVENT, latestRemoteState);
        } finally {
            correctingLocalState = false;
        }
    }

    function applyRecord(record) {
        if (record.type === RUNTIME_STATE) {
            latestRemoteState = record.event;
            correctingLocalState = true;
            try {
                events.emit(RUNTIME_EVENT, record.event);
            } finally {
                correctingLocalState = false;
            }
            return;
        }
        events.emit(record.type, record.event);
    }

    async function connectOnce() {
        const controller = typeof AbortController === "function" ? new AbortController() : null;
        currentAbort = controller;
        const headers = {};
        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }
        const response = await fetchImpl(`${target}${path}`, {
            headers,
            signal: controller ? controller.signal : undefined
        });
        if (!response.ok || !response.body) {
            throw new Error(`runtime events stream request failed with status ${response.status}`);
        }
        backoff = minBackoffMs;

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        try {
            // eslint-disable-next-line no-constant-condition
            while (true) {
                const { value, done } = await reader.read();
                if (done) {
                    break;
                }
                buffer += decoder.decode(value, { stream: true });
                let newlineIndex = buffer.indexOf("\n");
                while (newlineIndex !== -1) {
                    const line = buffer.slice(0, newlineIndex);
                    buffer = buffer.slice(newlineIndex + 1);
                    const record = decodeLine(line);
                    if (record) {
                        try {
                            applyRecord(record);
                        } catch (err) {
                            log.warn && log.warn(`node-red-temporal: failed applying a relayed runtime event: ${err.message}`);
                        }
                    }
                    newlineIndex = buffer.indexOf("\n");
                }
            }
        } finally {
            try {
                reader.releaseLock();
            } catch (err) {
                // stream may already be closed/errored
            }
        }
    }

    function scheduleReconnect() {
        if (stopped) {
            return;
        }
        reconnectTimer = setTimeout(() => {
            reconnectTimer = null;
            run();
        }, backoff);
        if (typeof reconnectTimer.unref === "function") {
            reconnectTimer.unref();
        }
        backoff = Math.min(backoff * 2, maxBackoffMs);
    }

    async function run() {
        if (stopped || active) {
            return;
        }
        active = true;
        try {
            await connectOnce();
        } catch (err) {
            if (!stopped) {
                log.warn && log.warn(`node-red-temporal: runtime events stream disconnected: ${err.message}`);
            }
        } finally {
            active = false;
            currentAbort = null;
            if (!stopped) {
                scheduleReconnect();
            }
        }
    }

    return {
        /** Idempotent: a second `start()` while already connected/connecting is a no-op. */
        start() {
            if (!stopped) {
                return;
            }
            stopped = false;
            backoff = minBackoffMs;
            events.on(RUNTIME_EVENT, onLocalRuntimeEvent);
            run();
        },
        /** Idempotent: safe to call multiple times, including before `start()`. */
        stop() {
            stopped = true;
            events.removeListener(RUNTIME_EVENT, onLocalRuntimeEvent);
            if (reconnectTimer) {
                clearTimeout(reconnectTimer);
                reconnectTimer = null;
            }
            if (currentAbort) {
                currentAbort.abort();
            }
        }
    };
}

module.exports = {
    DEFAULT_PATH,
    isForwardableCommsEvent,
    isForwardableRuntimeEvent,
    isEmptyStatus,
    encodeRecord,
    decodeLine,
    createStatusSnapshot,
    createRuntimeStateSnapshot,
    createRuntimeEventsRoute,
    createRuntimeEventsReceiver
};
